var n=`0368-raclette`;var i=`world-0368`;var a=`CH`;var r=`western-europe`;var s=4;var o=40;var l={en:`Raclette`,ua:`Раклет`};var u={en:`A raclette-style meal using Gruyère because raclette cheese is absent from the catalog; served with boiled potatoes and vegetables.`,ua:`Страва в стилі раклет із грюєром замість сиру раклет, якого немає в каталозі; подається з відвареною картоплею та овочами.`};var d=[{en:`Cook the listed ingredients in simmering water for about 24 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 24 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:24,i:[[`new-potato`,850,`g`],[`water`,1e3,`ml`]]},{en:`Roast in a preheated 190°C oven for about 12 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 12 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:12,i:[[`gruyere`,600,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`fermented-cucumber`,260,`g`],[`pearl-onion`,180,`g`],[`ground-black-pepper`,null,`to_taste`]]}];var g={slug:n,id:i,country:`CH`,region:r,servings:4,minutes:40,title:l,text:u,steps:d};export{a as country,g as default,i as id,o as minutes,r as region,s as servings,n as slug,d as steps,u as text,l as title};